import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import assert from 'node:assert/strict';
import {fileURLToPath} from 'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const pkg=JSON.parse(fs.readFileSync(path.join(root,'package.json'),'utf8'));
assert.equal(pkg.name,'dsh-image-viewer-fl0wer');
assert.equal(pkg.version,'0.1.17');
for(const file of ['lib/client.js','lib/index.js','cordis.patch.yml','locale/en.json','locale/zh.json','assets/icon.svg','README.md','MODIFICATIONS.md','LICENSE'])assert.ok(fs.statSync(path.join(root,file)).isFile(),file);
const source=fs.readFileSync(path.join(root,'lib/client.js'),'utf8');
assert.ok(!source.includes('sourceMappingURL='),'stale map link');
let registration;vm.runInNewContext(source,{window:{__ModuleLoader__:{load(value){registration=value;}}}});
assert.equal(registration.id,pkg.name);assert.equal(typeof registration.factory,'function');
assert.match(fs.readFileSync(path.join(root,'cordis.patch.yml'),'utf8'),/name: dsh-image-viewer-fl0wer/);
assert.match(fs.readFileSync(path.join(root,'README.md'),'utf8'),/WSL043/);
for(const marker of ['INK_COLORS','inkRegistry','ClipboardItem','readImageBlobWithFallback','imageSourceCandidates'])assert.ok(source.includes(marker),marker);
const index=await import(new URL('../lib/index.js',import.meta.url));assert.equal(typeof index.apply,'function');
console.log(JSON.stringify({package:pkg.name,version:pkg.version,registration:registration.id,checks:'static contract passed',interactiveTest:false}));
